import{_ as a,o as t,c as i,ao as o}from"./chunks/framework.csqrQb3W.js";const m=JSON.parse('{"title":"Pair copulas","description":"","frontmatter":{},"headers":[],"relativePath":"bestiary/pairs/overview.md","filePath":"bestiary/pairs/overview.md","lastUpdated":null}'),s={name:"bestiary/pairs/overview.md"};function l(r,e,c,n,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="Pair-copulas" tabindex="-1">Pair copulas <a class="header-anchor" href="#Pair-copulas" aria-label="Permalink to &quot;Pair copulas {#Pair-copulas}&quot;">​</a></h1><p>Pair copulas are the bivariate building blocks attached to vine edges. <code>PairCopula</code> is an alias for <code>Copulas.Copula{2}</code>, so the package uses the bivariate families provided by <code>Copulas.jl</code> while adding vine-oriented conditional kernels and selection logic.</p><p>The default automatic-selection set is intentionally smaller than the complete parametric catalog. It receives the strongest external correctness coverage and includes Gaussian, Student-t, Clayton, Gumbel, Frank, Joe, BB1, BB6, BB7, and BB8. Independence is controlled separately.</p><p>Use <code>family_set=:all</code> to expose the broader parametric set, or pass an explicit tuple of families when the candidate set is part of the model specification.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>This bestiary describes pair-copulas as vine building blocks. For the full mathematical treatment of a family, including domains and standalone distribution behavior, use the <code>Copulas.jl</code> documentation.</p></div>',5)])])}const h=a(s,[["render",l]]);export{m as __pageData,h as default};
